import"./BackToTop.astro_astro_type_script_index_0_lang.CvBe_npH.js";document.addEventListener("DOMContentLoaded",()=>{console.log("Initializing Intersection Observer animations..."),setTimeout(()=>{const n=new IntersectionObserver(e=>{e.forEach(t=>{if(t.isIntersecting){const s=t.target;s.classList.add("visible"),n.unobserve(s)}})},{threshold:.1,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll(".letter-char").forEach((e,t)=>{setTimeout(()=>{e.style.opacity="1",e.style.transform="translateX(0px) translateY(0px) scale(1)",e.style.filter="blur(0px)"},t*150)});const o=new IntersectionObserver(e=>{e.forEach(t=>{if(t.isIntersecting){const s=t.target;setTimeout(()=>{s.classList.add("visible")},200),o.unobserve(s)}})},{threshold:.15,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll("[data-animate]").forEach(e=>{o.observe(e)});const r=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&(setTimeout(()=>{document.getElementById("footerCome")?.classList.add("visible"),setTimeout(()=>{document.getElementById("footerSay")?.classList.add("visible")},100),setTimeout(()=>{document.getElementById("footerHello")?.classList.add("visible")},200),setTimeout(()=>{document.querySelector(".footer-chinese-wrap")?.classList.add("visible")},300)},300),r.unobserve(t.target))})},{threshold:.2}),i=document.querySelector(".footer");i&&r.observe(i),console.log("Animations initialized successfully")},800)});
